pub fn png(definition:i16,paint:u32)->Option<&'static [u8]> {
    let slot = match INDEX.binary_search_by_key(&(definition, paint), |e| (e.0, e.1)) {
        Ok(i) => i,
        Err(i) if paint == 0 && INDEX.get(i).is_some_and(|e| e.0 == definition) => i,
        Err(_) => return None,
    };
    let entry=INDEX[slot];let start=entry.2 as usize;PACK.get(start..start.checked_add(entry.3 as usize)?)
}
pub fn count()->usize {INDEX.len()}
